1	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
2	
3	vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
4	  getConfig: vi.fn(),
5	}));
6	
7	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
8	import { paymentMetadataHandler } from './paymentMetadata';
9	import { sendMagicLinkEmail } from './marketingCloud';
10	import type { SsrReq, SsrRes } from './types';
11	
12	const PAYMENTS_URL = 'https://payments.example.demandware.net/metadata';
13	const PAYMENTS_HOST = new URL(PAYMENTS_URL).hostname;
14	const MARKETING_CLOUD_AUTH_HOST = 'auth.marketingcloudapis.com';
15	const MARKETING_CLOUD_REST_HOST = 'rest.marketingcloudapis.com';
16	
17	/** Duration of the deliberate synchronous block used to occupy the event loop. */
18	const BLOCK_MS = 200;
19	/** Allowance for timer resolution when asserting on wall-clock durations. */
20	const TIMER_TOLERANCE_MS = 5;
21	/** Upper bound on how long to wait for Node to report an unhandled rejection. */
22	const REJECTION_SETTLE_TIMEOUT_MS = 1_000;
23	
24	type MockRes = SsrRes & { statusCode?: number; body?: unknown };
25	
26	function createMockRes(): MockRes {
27	  // Built incrementally: every member of SsrRes is assigned immediately below,
28	  // so the object is complete before it is returned.
29	  const res = {} as MockRes;
30	  res.status = vi.fn().mockImplementation((code: number) => {
31	    res.statusCode = code;
32	    return res;
33	  });
34	  res.json = vi.fn().mockImplementation((data: unknown) => {
35	    res.body = data;
36	    return res;
37	  });
38	  res.send = vi.fn().mockImplementation((data: unknown) => {
39	    res.body = data;
40	    return res;
41	  });
42	  res.setHeader = vi.fn().mockReturnValue(res);
43	  res.set = vi.fn().mockReturnValue(res);
44	  return res;
45	}
46	
47	function createMockReq(): SsrReq {
48	  return {
49	    protocol: 'https',
50	    body: { email_id: 'shopper@example.com', token: 'reset-token' },
51	    get: vi.fn().mockReturnValue('zimmermann.com'),
52	    params: {},
53	    query: {},
54	    headers: {},
55	  };
56	}
